#!/usr/bin/env python3
"""top-level-symbols.py <folder>: ONE CASE A FOLDER: `const k = Symbol("text")` at the top of a module is a name to the compiler, and o[k] an access by name: whatever can tell a symbol that is made when its line runs from a name that is there from the start."""
import os, sys
out = sys.argv[1]; cases = {}
def case(name, files):
    if isinstance(files, str): files = {"main.js": files}
    cases[name] = files
P = 'const say = (...a) => console.log(...a.map(v => typeof v === "symbol" ? v.toString() : v));\n'
case("read-and-store", P + 'const k = Symbol("handle");\nconst o = {}; o[k] = 1; o[k]++; say(o[k], k in o, Object.keys(o).length, Object.getOwnPropertySymbols(o)[0] === k);\n')
case("description", P + 'const a = Symbol("text"), b = Symbol(), c = Symbol(""), d = Symbol(undefined), e = Symbol(null), f = Symbol(5), g = Symbol("a:b;c"), h = Symbol("\\u00fc\\u4e00\\u00fc"), i = Symbol("\\u00fc\\u00fe");\nfor (const s of [a, b, c, d, e, f, g, h, i]) say(s.description, s.toString(), String(s), typeof s, Object(s).description);\n')
case("two-of-one-text-are-two", P + 'const a = Symbol("same"), b = Symbol("same");\nconst o = {}; o[a] = 1; o[b] = 2; say(a === b, o[a], o[b], Object.getOwnPropertySymbols(o).length);\n')
case("order-of-own-symbols", P + 'const a = Symbol("a"), b = Symbol("b"), c = Symbol("c");\nconst o = {}; o[c] = 1; o.x = 1; o[a] = 2; o[1] = 1; o[b] = 3; say(Object.getOwnPropertySymbols(o).map(String).join(), Reflect.ownKeys(o).map(String).join());\nconst l = { [b]: 1, [a]: 2, y: 1, [c]: 3 }; say(Reflect.ownKeys(l).map(String).join());\n')
case("registered", P + 'const a = Symbol.for("app.key"), b = Symbol.for("app.key"), c = Symbol("app.key");\nfunction again() { return Symbol.for("app.key"); }\nconst o = {}; o[a] = 1; say(a === b, a === c, a === again(), o[b], o[again()], o[c], Symbol.keyFor(a), Symbol.keyFor(c), a === (0, eval)(\'Symbol.for("app.key")\'), a === new Function(\'return Symbol.for("app." + "key")\')(), a === Symbol.for(["app", "key"].join(".")));\n')
case("registered-first-by-code-made-at-run-time", P + 'const early = (0, eval)(\'Symbol.for("made.early")\');\nconst a = Symbol.for("made.early"); const o = { [early]: 1 }; say(a === early, o[a]);\n')
case("weak-keys", P + 'const a = Symbol("plain"), r = Symbol.for("registered");\nconst w = new WeakMap(); w.set(a, 1); say(w.get(a), w.has(a)); try { w.set(r, 1); say("a registered symbol was taken"); } catch (e) { say(e.name); }\ntry { new WeakRef(a); say("ref"); } catch (e) { say(e.name); } try { new WeakRef(r); say("ref of a registered one"); } catch (e) { say(e.name); }\ntry { new WeakSet().add(r); say("set took it"); } catch (e) { say(e.name); }\n')
case("read-ahead-of-the-line", P + 'function early(o) { return o[k]; }\ntry { say(early({})); } catch (e) { say(e.name); }\nconst k = Symbol("late"); say(early({ [k]: 5 }));\n')
case("stored-ahead-of-the-line", P + 'function early(o) { o[k] = 1; return o; }\ntry { say(Reflect.ownKeys(early({})).length); } catch (e) { say(e.name); }\nconst k = Symbol("late"); say(Reflect.ownKeys(early({})).length);\n')
case("var-read-ahead-of-the-line", P + 'function early(o) { return o[k]; }\nsay(early({ undefined: "under the name undefined" }));\nvar k = Symbol("late"); say(early({ [k]: 5, undefined: "u" }));\n')
case("let-stored-twice", P + 'let k = Symbol("first"); const o = {}; o[k] = 1; const was = k; k = Symbol("second"); o[k] = 2; say(o[was], o[k], was === k, Object.getOwnPropertySymbols(o).length);\n')
case("let-stored-by-a-function", P + 'let k = Symbol("first"); function change() { k = Symbol("second"); }\nconst read = o => o[k]; const o = { [k]: 1 }; say(read(o)); change(); say(read(o)); o[k] = 2; say(read(o));\n')
case("chosen-by-a-condition", P + 'const yes = [true][0]; const k = yes ? Symbol("a") : Symbol("b"); const o = { [k]: 1 }; say(o[k], k);\n')
case("made-in-a-loop", P + 'const list = []; for (let i = 0; i < 3; i++) { const k = Symbol("loop"); list.push(k); }\nconst o = {}; for (const k of list) o[k] = 1; say(new Set(list).size, Object.getOwnPropertySymbols(o).length);\n')
case("made-in-a-function-called-twice", P + 'function make() { const k = Symbol("call"); return k; }\nconst a = make(), b = make(); say(a === b); const o = { [a]: 1 }; say(o[b]);\n')
case("made-in-a-block-and-a-try", P + 'let a, b; { a = Symbol("block"); } try { b = Symbol("try"); } finally {}\nconst o = { [a]: 1, [b]: 2 }; say(o[a], o[b]);\n')
case("the-text-has-an-effect", P + 'const log = []; const k = Symbol({ toString() { log.push("asked"); return "made"; } }); say(k, log.join());\ntry { Symbol(Symbol("inner")); } catch (e) { say(e.name); }\n')
case("symbol-is-shadowed", P + '{ const Symbol = text => "no symbol: " + text; const k = Symbol("x"); const o = {}; o[k] = 1; say(Object.keys(o).join(), typeof k); }\nfunction f(Symbol) { const k = Symbol("y"); return typeof k; } say(f(String));\n')
case("new-symbol-throws", P + 'try { const k = new Symbol("x"); say(typeof k); } catch (e) { say(e.name); }\n')
case("copies", P + 'const k = Symbol("k"); const copy = k; const again = copy; const o = {}; o[k] = 1; o[copy]++; o[again]++; say(o[k], copy === k, Object.getOwnPropertySymbols(o).length);\n')
case("seen-by-code-made-at-run-time", P + 'const k = Symbol("k"); const o = {}; o[k] = 7;\nsay(eval("o[k]"), new Function("o", "k", "return o[k]")(o, k), new Function("o", "return Object.getOwnPropertySymbols(o)[0]")(o) === k); new Function("o", "k", "o[k] = 8")(o, k); say(o[k]);\n')
case("every-way-to-use-a-key", P + 'const k = Symbol("k"); const o = {};\nObject.defineProperty(o, k, { value: 1, writable: true, enumerable: false, configurable: true }); say(o[k], JSON.stringify(Object.getOwnPropertyDescriptor(o, k)), o.propertyIsEnumerable(k), Object.hasOwn(o, k), o.hasOwnProperty(k), Reflect.has(o, k), Reflect.get(o, k), k in o);\nsay(Reflect.set(o, k, 2), o[k], delete o[k], k in o, o[k]); const { [k]: taken = "default" } = o; say(taken); o[k] = 3; const { [k]: there, ...rest } = o; say(there, Reflect.ownKeys(rest).length);\nsay(Reflect.ownKeys({ ...o }).length, Reflect.ownKeys(Object.assign({}, o)).length, JSON.stringify(o), Object.entries(o).length); for (const x in o) say("in a for-in", x);\n')
case("a-proxy-sees-the-symbol", P + 'const k = Symbol("k"); const seen = [];\nconst p = new Proxy({}, { get(t, key) { seen.push(key === k); return 1; }, set(t, key, v) { seen.push(key === k); return true; }, has(t, key) { seen.push(key === k); return true; }, deleteProperty(t, key) { seen.push(key === k); return true; } });\np[k]; p[k] = 1; k in p; delete p[k]; say(seen.join());\n')
case("members-of-classes", P + 'const m = Symbol("method"), g = Symbol("getter"), s = Symbol("static"), f = Symbol("field");\nclass A { [m]() { return "m"; } get [g]() { return "g"; } static [s]() { return "s"; } [f] = "f"; }\nclass B extends A { [m]() { return "B" + super[m](); } }\nconst b = new B(); say(b[m](), b[g], A[s](), B[s](), b[f], Reflect.ownKeys(A.prototype).map(String).join(), Reflect.ownKeys(b).map(String).join(), A.prototype[m].name, Object.getOwnPropertyDescriptor(A.prototype, g).get.name);\n')
case("inherited-and-shadowed", P + 'const k = Symbol("k"); const base = { [k]: "base" }; const o = Object.create(base); say(o[k], Object.hasOwn(o, k)); o[k] = "own"; say(o[k], base[k]); delete o[k]; say(o[k]);\nconst setter = { set [k](v) { this.got = v; }, get [k]() { return "from the getter"; } }; const c = Object.create(setter); c[k] = 5; say(c.got, c[k], Object.hasOwn(c, k));\n')
case("frozen-and-sealed", P + '"use strict"; const k = Symbol("k"); const o = Object.freeze({ [k]: 1 }); try { o[k] = 2; } catch (e) { say(e.name); } say(o[k]); const n = Object.preventExtensions({}); try { n[k] = 1; } catch (e) { say(e.name); } say(k in n);\n')
case("on-primitives-and-nil", P + 'const k = Symbol("k"); say((5)[k], "text"[k], true[k], k[k]); for (const v of [null, undefined]) { try { say(v[k]); } catch (e) { say(e.name, e.message.length > 0); } try { v[k] = 1; } catch (e) { say(e.name); } }\n')
case("on-arrays-functions-and-host-objects", P + 'const k = Symbol("k"); const a = [1]; a[k] = "a"; function f() {} f[k] = "f"; const m = new Map(); m[k] = "m"; const d = new Date(0); d[k] = "d"; const e = new Error("x"); e[k] = "e"; const u = new Uint8Array(1); u[k] = "u"; const p = Promise.resolve(); p[k] = "p"; say(a[k], a.length, f[k], m[k], m.size, d[k], e[k], u[k], p[k], globalThis[k]); globalThis[k] = "g"; say(globalThis[k]);\n')
case("many-shapes-through-one-site", P + 'const k = Symbol("k"); const read = o => o[k]; const list = []; for (let i = 0; i < 40; i++) { const o = {}; for (let j = 0; j < i % 7; j++) o["p" + j] = j; if (i % 3) o[k] = i; list.push(o); }\nsay(list.map(read).join());\n')
case("printed", 'const k = Symbol("k"), n = Symbol(), r = Symbol.for("r"); console.log(k, n, r, { [k]: 1, [n]: 2, [r]: 3 }, [k]);\n')
case("exported-and-imported", {"main.js": P + 'import { k, stamp, read } from "./lib.js";\nimport * as ns from "./lib.js";\nconst o = {}; stamp(o); say(o[k], read(o), ns.k === k, o[ns.k]); o[k] = 2; say(read(o));\n', "lib.js": 'export const k = Symbol("shared");\nexport function stamp(o) { o[k] = 1; }\nexport function read(o) { return o[k]; }\n'})
case("a-cycle-reads-it-early", {"main.js": P + 'import { k } from "./a.js"; say(k);\n', "a.js": 'import { early } from "./b.js";\nexport const k = Symbol("a");\nconsole.log(early());\n', "b.js": 'import { k } from "./a.js";\nlet first; try { first = String(k); } catch (e) { first = e.name; }\nexport function early() { return first + " then " + String(k); }\n'})
case("commonjs-exports", {"main.cjs": P + 'const { k, stamp } = require("./lib.cjs"); const o = {}; stamp(o); say(o[k], Object.getOwnPropertySymbols(o)[0] === k);\n', "lib.cjs": 'const k = Symbol("cjs"); exports.k = k; exports.stamp = o => { o[k] = 1; };\n'})
case("a-module-evaluated-again", {"main.cjs": P + 'const first = require("./lib.cjs"); const o = {}; first.stamp(o); delete require.cache[require.resolve("./lib.cjs")]; const second = require("./lib.cjs");\nsay(first === second, first.k === second.k, first.read(o), second.read(o), Object.getOwnPropertySymbols(o).length); second.stamp(o); say(Object.getOwnPropertySymbols(o).length);\n', "lib.cjs": 'const k = Symbol("again"); exports.k = k; exports.stamp = o => { o[k] = 1; }; exports.read = o => o[k];\n'})
case("an-es-module-imported-again-with-a-query", {"main.js": P + 'const first = await import("./lib.js"); const second = await import("./lib.js?again");\nconst o = {}; first.stamp(o); say(first.k === second.k, first.read(o), second.read(o));\n', "lib.js": 'export const k = Symbol("again");\nexport function stamp(o) { o[k] = 1; }\nexport function read(o) { return o[k]; }\n'})
case("a-worker-has-its-own", {"main.js": P + 'import { k } from "./lib.js";\nconst w = new Worker(new URL("./worker.js", import.meta.url).href); const got = await new Promise(r => { w.onmessage = e => r(e.data); }); w.terminate(); say(got, k);\ntry { structuredClone(k); } catch (e) { say(e.name); }\n', "lib.js": 'export const k = Symbol("per thread");\n', "worker.js": 'import { k } from "./lib.js";\nconst o = { [k]: 1 }; postMessage([o[k], k.description, Object.getOwnPropertySymbols(o).length].join());\n'})
case("mocked", {"main.test.ts": 'import { test, mock } from "bun:test";\nimport { read, stamp } from "./user";\nconst other = Symbol("other");\nmock.module("./lib", () => ({ k: other }));\ntest("case", () => { const o: any = {}; stamp(o); console.log(Object.getOwnPropertySymbols(o)[0] === other, read(o), o[other]); });\n', "lib.ts": 'export const k: symbol = Symbol("real");\n', "user.ts": 'import { k } from "./lib";\nexport function stamp(o: any): void { o[k] = 1; }\nexport function read(o: any): unknown { return o[k]; }\n'})
case("typescript-unique-symbols", {"main.ts": 'const k: unique symbol = Symbol("typed"); const j = Symbol("inferred");\ninterface Has { [k]: number; [j]?: string }\nconst o: Has = { [k]: 1 }; o[k]++; o[j] = "s"; const a: any = o;\nconsole.log(o[k], o[j], a[k], a[j], Reflect.ownKeys(o).map(String).join());\nclass C { [k] = 5; [j](): string { return "m"; } } const c = new C(); console.log(c[k], c[j](), (c as any)[k]);\n'})
case("after-collections", P + 'const k = Symbol("kept"); const o = { [k]: 1 }; let last; for (let i = 0; i < 200000; i++) last = { [Symbol("garbage " + (i & 7))]: i }; if (typeof Bun !== "undefined") Bun.gc(true); say(o[k], Object.getOwnPropertySymbols(o)[0] === k, k.description);\n')
case("to-primitive-and-well-known-beside", P + 'const k = Symbol("k"); const o = { [k]: 1, [Symbol.toPrimitive]() { return 42; }, [Symbol.toStringTag]: "Tagged", *[Symbol.iterator]() { yield 1; } }; say(+o, String(Object.prototype.toString.call(o)), [...o].join(), o[k]);\ntry { say(k + ""); } catch (e) { say(e.name); } try { say(`${k}`); } catch (e) { say(e.name); } try { say(+k); } catch (e) { say(e.name); } say(!!k, k == k, Object(k) == k, Object(k) === k);\n')
for name, files in cases.items():
    os.makedirs(f"{out}/{name}", exist_ok=True)
    for f, text in files.items(): open(f"{out}/{name}/{f}", "w").write(text)
print(len(cases), "cases")
